import{_ as t,o as a,c as r,a3 as o}from"./chunks/framework.Crt1tuW8.js";const m=JSON.parse('{"title":"TP2 — Partie B (évaluation supervisée)","description":"","frontmatter":{"title":"TP2 — Partie B (évaluation supervisée)","aside":false},"headers":[],"relativePath":"travaux/tp2-partie-b.md","filePath":"travaux/tp2-partie-b.md"}'),s={name:"travaux/tp2-partie-b.md"};function i(n,e,l,d,u,c){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="tp2-—-partie-b-—-evaluation-supervisee-7" tabindex="-1">TP2 — Partie B — évaluation supervisée (7 %) <a class="header-anchor" href="#tp2-—-partie-b-—-evaluation-supervisee-7" aria-label="Permalink to &quot;TP2 — Partie B — évaluation supervisée (7 %)&quot;">​</a></h1><div class="my-6 rounded-lg border border-yellow-300 bg-yellow-50 p-4 text-yellow-900"><strong>Cette page est publiée au début de la période du 22 octobre.</strong><br> Les questions vous sont remises séparément par l&#39;enseignant. </div><ul><li>Durée : <strong>1 heure</strong>, en début de période.</li><li>Individuel.</li><li>Porte sur les mêmes notions que la partie A : <code>insert</code>, <code>select</code>, opérateurs, sous-requêtes, <code>update</code> et <code>delete</code> ciblés.</li></ul><hr><h2 id="avant-de-commencer" tabindex="-1">Avant de commencer <a class="header-anchor" href="#avant-de-commencer" aria-label="Permalink to &quot;Avant de commencer&quot;">​</a></h2><ol><li><p><strong>Importez la base fournie</strong> : ouvrez le fichier <code>.sql</code> remis par l&#39;enseignant dans DBeaver (<code>Fichier</code> → <code>Ouvrir un fichier…</code>), exécutez tout le script avec <code>Alt + X</code>, puis rafraîchissez l&#39;arborescence avec <code>F5</code>.</p><p>La structure est <strong>la même qu&#39;à la partie A</strong>; seules les données changent. Il n&#39;y a donc rien de nouveau à apprendre sur le modèle.</p></li><li><p>Créez un nouveau script SQL et nommez votre fichier <strong><code>tp2b_prenom_nom.sql</code></strong>.</p></li><li><p>Commencez votre fichier par son <code>use</code> :</p></li></ol><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">use</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> guilde_partie_b;</span></span></code></pre></div><ol start="4"><li>Numérotez vos réponses avec des commentaires : <code>-- 1)</code>, <code>-- 2)</code>, et ainsi de suite.</li></ol><hr><h2 id="pendant-l-evaluation" tabindex="-1">Pendant l&#39;évaluation <a class="header-anchor" href="#pendant-l-evaluation" aria-label="Permalink to &quot;Pendant l&#39;évaluation&quot;">​</a></h2><div class="my-6 rounded-lg border border-red-300 bg-red-50 p-4 text-red-900"><strong>Aide permise</strong><br> Le <strong>site du cours uniquement</strong>. Aucune autre aide n&#39;est permise : autres sites Web, intelligence artificielle, notes d&#39;un collègue, échanges entre étudiants.<br> Tous les onglets autres que le site du cours doivent être fermés au début de la période. </div><p>Conseils :</p><ul><li>Avant chaque <code>update</code> ou <code>delete</code>, écrivez d&#39;abord le <code>select</code> qui retourne les lignes visées. Si le <code>select</code> est bon, le <code>where</code> est bon.</li><li>Relisez la question après avoir écrit la requête : les colonnes demandées, le tri et l&#39;élimination des doublons font partie de la réponse.</li><li>Sauvegardez votre fichier régulièrement.</li></ul><hr><h2 id="remise" tabindex="-1">Remise <a class="header-anchor" href="#remise" aria-label="Permalink to &quot;Remise&quot;">​</a></h2><p>Remettez votre fichier <code>tp2b_prenom_nom.sql</code> sur LÉA <strong>avant la fin de la période</strong>. Aucune période de grâce.</p><hr><h2 id="bareme" tabindex="-1">Barème <a class="header-anchor" href="#bareme" aria-label="Permalink to &quot;Barème&quot;">​</a></h2><p>Chaque question vaut le même nombre de points.</p><table tabindex="0"><thead><tr><th>Niveau</th><th>Description</th></tr></thead><tbody><tr><td><strong>Complet</strong></td><td>La requête s&#39;exécute et retourne exactement le résultat demandé : lignes, colonnes et ordre.</td></tr><tr><td><strong>Partiel</strong></td><td>La logique est bonne, mais il manque un détail — colonne superflue ou manquante, tri absent, doublons non éliminés, borne d&#39;intervalle inexacte.</td></tr><tr><td><strong>Nul</strong></td><td>La requête ne s&#39;exécute pas, ou ne répond pas à la demande.</td></tr></tbody></table><p>La grille complète du TP2 est dans les <a href="./../grilles/grille-tp2">grilles d&#39;évaluation</a>.</p>',21)])])}const h=t(s,[["render",i]]);export{m as __pageData,h as default};
